<?php require_once __DIR__.'/../php/includes/bootstrap.php'; require_login(); $user=current_user();
$n=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 5');$n->execute([$user['id']]);$notifications=$n->fetchAll();
page_header('Your dashboard'); ?>
<section class="welcome-panel"><div><p class="eyebrow">YOUR WORKSPACE</p><h2>Welcome, <?= e($user['full_name']) ?></h2><p class="muted">Signed in as <?= e(ucfirst($user['role'])) ?>.</p></div><span class="role-pill"><?= e($user['role']) ?></span></section>
<?php if($user['role']==='student'): ?><div class="card-grid"><a class="feature-card" href="programme.php"><span class="feature-icon">01</span><h3>Programmes & payment</h3><p>Explore tutoring programmes and submit a demo payment for approval.</p></a><a class="feature-card" href="booking.php"><span class="feature-icon">02</span><h3>Book a session</h3><p>Choose an eligible programme and an available tutor.</p></a></div><?php $b=$pdo->prepare("SELECT b.*,p.name programme,u.full_name tutor FROM bookings b JOIN programmes p ON p.id=b.programme_id JOIN users u ON u.id=b.tutor_id WHERE b.student_id=? ORDER BY b.session_date DESC,b.start_time DESC");$b->execute([$user['id']]);$rows=$b->fetchAll(); ?>
<section class="panel"><h2>Your sessions</h2><?php if(!$rows): ?><p class="muted">No sessions booked yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Programme</th><th>Tutor</th><th>Date</th><th>Time</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['programme'])?></td><td><?=e($r['tutor'])?></td><td><?=e($r['session_date'])?></td><td><?=e(substr($r['start_time'],0,5))?>–<?=e(substr($r['end_time'],0,5))?></td><td><span class="status"><?=e($r['status'])?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php elseif($user['role']==='tutor'): ?><div class="card-grid"><a class="feature-card" href="availability.php"><span class="feature-icon">01</span><h3>Manage availability</h3><p>Add weekday time slots when students can book you.</p></a></div><?php $s=$pdo->prepare("SELECT b.*,p.name programme,u.full_name student FROM bookings b JOIN programmes p ON p.id=b.programme_id JOIN users u ON u.id=b.student_id WHERE b.tutor_id=? AND b.status='confirmed' ORDER BY b.session_date,b.start_time");$s->execute([$user['id']]);$rows=$s->fetchAll(); ?><section class="panel"><h2>Assigned sessions</h2><?php if(!$rows): ?><p class="muted">No assigned sessions yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Student</th><th>Programme</th><th>Date</th><th>Time</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['student'])?></td><td><?=e($r['programme'])?></td><td><?=e($r['session_date'])?></td><td><?=e(substr($r['start_time'],0,5))?>–<?=e(substr($r['end_time'],0,5))?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php else: ?><a class="button" href="admin.php">Open administration</a><?php endif; ?>
<section class="panel"><h2>Recent notifications</h2><?php if(!$notifications): ?><p class="muted">You are all caught up.</p><?php else: ?><ul class="notification-list"><?php foreach($notifications as $item): ?><li><?=e($item['message'])?><small><?=e($item['created_at'])?></small></li><?php endforeach; ?></ul><?php endif; ?></section>
<?php page_footer(); ?>